 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d',{alpha:false});this.map=buildMap();this.w=1200;this.h=800;this.dpr=1;this.scale=1;this.camX=0;this.camY=0;this.reducedMotion=window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches||false;this.resize()}
